171	    constexpr std::size_t reduce_tile_bytes = tile_storage_bytes<ReduceTileF_T>();
172	    constexpr std::size_t xexp_bytes = tile_buffer_total_bytes<TileDataH_T, XexpBuffers>();
173	    constexpr std::size_t out_tile_bytes = tile_storage_bytes<TileOutT>();
174	    constexpr std::size_t union_stride = (tile_storage_bytes<TileDataF_T>() > tile_storage_bytes<TileOutT>()) ?
175	                                             tile_storage_bytes<TileDataF_T>() :
176	                                             tile_storage_bytes<TileOutT>();
