183	    uint32_t offset = 0;
184	    TASSIGN(runningOTile, offset);
185	    offset += out_tile_bytes;
186	    offset = assign_tile_buffers_union(srcTiles, pvTile, offset);
187	
188	    TASSIGN(m1_local_max, offset);
189	    offset += static_cast<uint32_t>(reduce_tile_bytes);
190	
191	    TASSIGN(m2_global_max, offset);
192	    offset += static_cast<uint32_t>(reduce_tile_bytes);
193	
194	    uint32_t tmp_float_offset = offset;
195	    TASSIGN(input_reduce_tmp, tmp_float_offset);
196	    offset += static_cast<uint32_t>(float_tile_bytes) / 8;
197	
198	    TASSIGN(triu, offset);
199	    offset += static_cast<uint32_t>(float_tile_bytes);
200	
201	    TASSIGN(l1_local_sum, offset);
202	    offset += static_cast<uint32_t>(reduce_tile_bytes);
203	
204	    TASSIGN(l2_global_sum, offset);
205	    offset += static_cast<uint32_t>(reduce_tile_bytes);
