534	        if constexpr (INTERMEDIATE_CHECK) {
535	            // On the final row_slice, emit the exp_max for this subblock only (Cube_S0 / VEC_CORES rows)
536	            if (row_slice == static_cast<int>(kTileFactor) - 1) {
