18	// -----------------------------------------------------------------------------
19	// FlashAttention streaming softmax (tile-level)
20	//
21	// Given one QK tile X (fp32), compute x_exp = exp(scale * (X - new_global_max)).
22	// This function maintains per-row running state (global_max, global_sum) so that we can
23	// stream over S1 tiles without materializing the full attention matrix.
24	//
25	// Performance notes:
26	// - Keep intermediate computations in fp32 for numerical stability.
27	// - The `init` specialization initializes running state for the first S1 tile.
28	// - The 2D->1D reshape for TCVT is used to avoid layout constraints and keep the cast fast.
29	// -----------------------------------------------------------------------------
30	
31	constexpr PTO_INTERNAL float constexpr_sqrt(float x)
32	{
33	    if (x <= 0.0f)
34	        return 0.0f;
35	    float guess = x;
36	    for (int i = 0; i < 8; ++i) {
37	        guess = 0.5f * (guess + x / guess);
38	    }
39	    return guess;
40	}
41	
42	constexpr AICORE inline float constexpr_inv_sqrt(float x) { return 1.0f / constexpr_sqrt(x); }
43	
44	template <int HEAD_SIZE, bool CAUSAL_MASK, typename ReduceTileD1, typename TileDataD2, typename TileDataS1>
45	AICORE inline void softmax_opt_fa_init_impl(
46	    TileDataD2 __out__ x_exp, TileDataS1 __in__ input_x, ReduceTileD1 __out__ local_max, ReduceTileD1 __out__ local_sum,
47	    ReduceTileD1 __out__ new_global_max, ReduceTileD1 __out__ new_global_sum, ReduceTileD1 __out__ exp_max,
48	    TileDataS1 __out__ tmp_float, TileDataS1 __out__ p_tile_f32, TileDataS1 triu, int s0_index, int s1_index)
49	{
50	    (void)local_max;
51	    (void)exp_max;
52	    (void)local_sum;
53	
54	    constexpr float scale = constexpr_inv_sqrt(HEAD_SIZE);
55	    using Tile1D_fp32 = Tile<
56	        TileType::Vec, float, 1, TileDataS1::Rows * TileDataS1::Cols, BLayout::RowMajor, 1,
57	        TileDataS1::Rows * TileDataS1::Cols>;
58	    using Tile1D_out = Tile<
59	        TileType::Vec, typename TileDataD2::DType, 1, TileDataS1::Rows * TileDataS1::Cols, BLayout::RowMajor, 1,
60	        TileDataS1::Rows * TileDataS1::Cols>;
61	    Tile1D_fp32 p_tile_f32_1d;
62	    Tile1D_out x_exp_1d;
63	    if constexpr (CAUSAL_MASK) {
64	        if (s0_index / TileDataS1::Cols == s1_index / TileDataS1::Cols) {
65	            constexpr float negInf = -3.40282e+38;
66	            TTRI<TileDataS1, 1>(triu, 1 + (s0_index % TileDataS1::Cols));
67	#if defined(__DAV_C220_VEC__)
68	            pipe_barrier(PIPE_V);
69	#endif
70	            TMULS(triu, triu, negInf);
71	#if defined(__DAV_C220_VEC__)
72	            pipe_barrier(PIPE_V);
73	#endif
74	            TADD(input_x, input_x, triu);
75	#if defined(__DAV_C220_VEC__)
76	            pipe_barrier(PIPE_V);
77	#endif
78	        }
79	    }
80	    // FA2.0 init mode
81	    TROWMAX(new_global_max, input_x, tmp_float);
82	#if defined(__DAV_C220_VEC__)
83	    pipe_barrier(PIPE_V);
84	#endif
85	    TROWEXPANDSUB(p_tile_f32, input_x, new_global_max);
86	    TMULS(p_tile_f32, p_tile_f32, scale);
87	    TEXP(p_tile_f32, p_tile_f32);
88	#if defined(__DAV_C220_VEC__)
89	    pipe_barrier(PIPE_V);
90	#endif
91	    TROWSUM(new_global_sum, p_tile_f32, tmp_float);
92	
93	    TRESHAPE(p_tile_f32_1d, p_tile_f32);
94	    TRESHAPE(x_exp_1d, x_exp);
95	    TCVT(x_exp_1d, p_tile_f32_1d, RoundMode::CAST_ROUND);
96	}
97	
98	template <int HEAD_SIZE, bool CAUSAL_MASK, typename ReduceTileD1, typename TileDataD2, typename TileDataS1>
99	AICORE inline void softmax_opt_fa_not_init_impl(
100	    TileDataD2 __out__ x_exp, TileDataS1 __in__ input_x, ReduceTileD1 __out__ local_max, ReduceTileD1 __out__ local_sum,
101	    ReduceTileD1 __out__ new_global_max, ReduceTileD1 __out__ new_global_sum, ReduceTileD1 __out__ exp_max,
102	    TileDataS1 __out__ tmp_float, TileDataS1 __out__ p_tile_f32, TileDataS1 triu, int s0_index, int s1_index)
103	{
104	    constexpr float scale = constexpr_inv_sqrt(HEAD_SIZE);
105	
106	    using ReduceTileD2 = Tile<TileType::Vec, float, 1, ReduceTileD1::Rows, BLayout::RowMajor, 1, ReduceTileD1::Rows>;
107	    using Tile1D_fp32 = Tile<
108	        TileType::Vec, float, 1, TileDataS1::Rows * TileDataS1::Cols, BLayout::RowMajor, 1,
109	        TileDataS1::Rows * TileDataS1::Cols>;
110	    using Tile1D_out = Tile<
111	        TileType::Vec, typename TileDataD2::DType, 1, TileDataS1::Rows * TileDataS1::Cols, BLayout::RowMajor, 1,
112	        TileDataS1::Rows * TileDataS1::Cols>;
113	
114	    ReduceTileD2 tmp_shw_local_max;
115	    ReduceTileD2 tmp_shw_new_global_max;
116	    ReduceTileD2 tmp_shw_exp_max;
117	    ReduceTileD2 tmp_shw_new_global_sum;
118	    ReduceTileD2 tmp_shw_local_sum;
119	    Tile1D_fp32 p_tile_f32_1d;
120	    Tile1D_out x_exp_1d;
121	
122	    if constexpr (CAUSAL_MASK) {
123	        if (s0_index / TileDataS1::Cols == s1_index / TileDataS1::Cols) {
124	            constexpr float negInf = -3.40282e+38;
125	            TTRI<TileDataS1, 1>(triu, 1 + (s0_index % TileDataS1::Cols));
126	#if defined(__DAV_C220_VEC__)
127	            pipe_barrier(PIPE_V);
128	#endif
129	            TMULS(triu, triu, negInf);
130	#if defined(__DAV_C220_VEC__)
131	            pipe_barrier(PIPE_V);
132	#endif
133	            TADD(input_x, input_x, triu);
134	#if defined(__DAV_C220_VEC__)
135	            pipe_barrier(PIPE_V);
136	#endif
137	        }
138	    }
139	    // FA2.0 streaming mode (not first tile): update (global_max, global_sum) and rescale old sums.
140	    TROWMAX(local_max, input_x, tmp_float);
141	#if defined(__DAV_C220_VEC__)
142	    pipe_barrier(PIPE_V);
143	#endif
144	    TRESHAPE(tmp_shw_local_max, local_max);
145	    TRESHAPE(tmp_shw_new_global_max, new_global_max);
146	    TMAX(tmp_shw_local_max, tmp_shw_local_max, tmp_shw_new_global_max);
147	#if defined(__DAV_C220_VEC__)
148	    pipe_barrier(PIPE_V);
149	#endif
150	    TRESHAPE(tmp_shw_exp_max, exp_max);
151	    TSUB(tmp_shw_exp_max, tmp_shw_new_global_max, tmp_shw_local_max);
152	#if defined(__DAV_C220_VEC__)
153	    pipe_barrier(PIPE_V);
154	#endif
155	
156	    TMULS(tmp_shw_new_global_max, tmp_shw_local_max, 1.0f); // just copy
157	#if defined(__DAV_C220_VEC__)
158	    pipe_barrier(PIPE_V);
159	#endif
160	    TROWEXPANDSUB(p_tile_f32, input_x, local_max);
161	    TMULS(tmp_shw_exp_max, tmp_shw_exp_max, scale);
162	    TMULS(p_tile_f32, p_tile_f32, scale);
163	    TEXP(tmp_shw_exp_max, tmp_shw_exp_max);
164	    TRESHAPE(tmp_shw_exp_max, exp_max);
165	    TEXP(p_tile_f32, p_tile_f32);
166	    TRESHAPE(tmp_shw_exp_max, exp_max);
167	
168	    TRESHAPE(p_tile_f32_1d, p_tile_f32);
169	    TRESHAPE(x_exp_1d, x_exp);
170	    TCVT(x_exp_1d, p_tile_f32_1d, RoundMode::CAST_ROUND);
171	#if defined(__DAV_C220_VEC__)
172	    pipe_barrier(PIPE_V);
173	#endif
174	    TRESHAPE(tmp_shw_new_global_sum, new_global_sum);
175	    TMUL(tmp_shw_new_global_sum, tmp_shw_exp_max, tmp_shw_new_global_sum);
176	    TROWSUM(local_sum, p_tile_f32, tmp_float);
177	    TRESHAPE(tmp_shw_local_sum, local_sum);
178	#if defined(__DAV_C220_VEC__)
179	    pipe_barrier(PIPE_V);
180	#endif
181	    TADD(tmp_shw_new_global_sum, tmp_shw_new_global_sum, tmp_shw_local_sum);
182	}
183	
184	template <
185	    bool init = false, int HEAD_SIZE, bool CAUSAL_MASK, typename ReduceTileD1, typename TileDataD2, typename TileDataS1>
186	AICORE inline void pto_macro_fa_softmax(
187	    TileDataD2 __out__ x_exp, TileDataS1 __in__ input_x, ReduceTileD1 __out__ local_max, ReduceTileD1 __out__ local_sum,
188	    ReduceTileD1 __in__ new_global_max, ReduceTileD1 __out__ new_global_sum, ReduceTileD1 __out__ exp_max,
189	    TileDataS1 __out__ input_reduce_tmp, TileDataS1 __out__ p_tile_fp32, TileDataS1 triu, int s0_index, int s1_index)
190	{
191	    if (s1_index <= s0_index || !CAUSAL_MASK) {
192	        if constexpr (init) {
193	            softmax_opt_fa_init_impl<HEAD_SIZE, CAUSAL_MASK, ReduceTileD1, TileDataD2, TileDataS1>(
194	                x_exp, input_x, local_max, local_sum, new_global_max, new_global_sum, exp_max, input_reduce_tmp,
195	                p_tile_fp32, triu, s0_index, s1_index);
196	        } else {
197	            softmax_opt_fa_not_init_impl<HEAD_SIZE, CAUSAL_MASK, ReduceTileD1, TileDataD2, TileDataS1>(
198	                x_exp, input_x, local_max, local_sum, new_global_max, new_global_sum, exp_max, input_reduce_tmp,
199	                p_tile_fp32, triu, s0_index, s1_index);
200	        }
201	    } else if constexpr (CAUSAL_MASK) {
202	        TMULS(x_exp, x_exp, 0.0);
203	        TMULS(exp_max, exp_max, 0.0);
204	#if defined(__DAV_C220_VEC__)
205	        pipe_barrier(PIPE_V);
206	#endif
207	        TADDS(exp_max, exp_max, 1.0);
208	#if defined(__DAV_C220_VEC__)
209	        pipe_barrier(PIPE_V);
210	#endif
211	    }
212	}
213	
214	} // namespace pto
215	
216	#endif
