11	#ifndef PTO_MACRO_MATMUL_HPP
12	#define PTO_MACRO_MATMUL_HPP
13	
14	#include <pto/pto-inst.hpp>
15	#include <pto/common/memory.hpp>
16	
17	#define CUBE_K_256 256
18	#define CUBE_K_128 128
19	#define CUBE_K_64 64
20	#define CUBE_K_SMALLEST 32
21	
22	namespace pto {
23	
24	/**
25	 * Layout type for matrix multiplication operations.
26	 * First letter represents the layout of matrix A, second letter represents matrix B.
27	 * N = Normal (Row-major), T = Transposed (Column-major)
28	 */
29	enum class layout_t {
30	    NN, // Matrix A: Normal, Matrix B: Normal
31	    NT, // Matrix A: Normal, Matrix B: Transposed
32	    TN, // Matrix A: Transposed, Matrix B: Normal
33	    TT, // Matrix A: Transposed, Matrix B: Transposed
34	    NONE
35	};
36	
37	enum class AccMode {
38	    Init,           // auto phase, first slice initializes, rest accumulate
39	    Acc,            // auto phase, all slices accumulate into existing C
40	    InitPartialSum, // explicitly partial, first slice initializes
41	    InitFinalSum,   // explicitly final, first slice initializes
42	    AccPartialSum,  // explicitly partial, all slices accumulate
43	    AccFinalSum,    // explicitly final, all slices accumulate
44	};
45	
46	#define L0A_BUF0 ((__ca__ half*)(__ca__ char*)0x0)
47	#define L0A_BUF1 ((__ca__ half*)(__ca__ char*)0x8000)
48	#define L0B_BUF0 ((__ca__ half*)(__ca__ char*)0x0)
49	#define L0B_BUF1 ((__ca__ half*)(__ca__ char*)0x8000)
50	#define L0C_BUF0 ((__ca__ half*)(__ca__ char*)0x0)
51	#define L0C_BUF1 ((__ca__ half*)(__ca__ char*)0x20000)
52	
53	#define LAST_LOOP(x, n) ((x) == ((n) - 1))
54	#define UNIT_FLAG_ENABLE(i, n) (LAST_LOOP(i, n) ? 3 : 2)
55	
56	AICORE inline uint64_t getPingPong(uint32_t flip)
57	{
58	    static uint64_t pingpong = 0;
59	    if (flip) {
60	        pingpong = 1 - pingpong;
61	    }
62	    return pingpong;
63	}
64	
65	// Memory constraints (L0 ping-pong is 32 KiB per buffer in this implementation).
66	// Tuning knob: if you change L0 layout or buffer addresses, re-check these constraints.
67	constexpr uint32_t MEM_BUFFER_SIZE_BYTES = 64 * 1024 / 2; // 64KB per buffer with pingpong (32KB)
68	constexpr uint32_t HALF_SIZE_BYTES = 2;                   // sizeof(half) = 2 bytes
69	
70	/**
71	 * Calculate the largest Cube_K value that fits in the 64KB memory buffer.
72	 * Checks if both Cube_M * Cube_K (left matrix) and Cube_K * Cube_N (right matrix)
73	 * can fit within the 64KB buffer.
74	 *
75	 * @param Cube_M - The tile dimension M
76	 * @param Cube_N - The tile dimension N
77	 * @return - Largest Cube_K value (32, 64, 128, or 256) that fits in memory
78	 */
79	// Choose the largest Cube_K that fits both L0A (Cube_M x Cube_K) and L0B (Cube_K x Cube_N)
80	// so TMATMUL stays compute-dense while respecting L0 ping-pong capacity.
81	AICORE inline constexpr uint32_t calculateFittingCubeK(uint32_t Cube_M, uint32_t Cube_N)
82	{
83	    uint32_t bestCubeK = CUBE_K_SMALLEST; // Default to smallest value
84	
85	    // Test candidates from largest to smallest to find the largest that fits
86	    if (Cube_M * CUBE_K_256 * HALF_SIZE_BYTES <= MEM_BUFFER_SIZE_BYTES &&
87	        CUBE_K_256 * Cube_N * HALF_SIZE_BYTES <= MEM_BUFFER_SIZE_BYTES) {
88	        bestCubeK = CUBE_K_256;
89	    } else if (
90	        Cube_M * CUBE_K_128 * HALF_SIZE_BYTES <= MEM_BUFFER_SIZE_BYTES &&
91	        CUBE_K_128 * Cube_N * HALF_SIZE_BYTES <= MEM_BUFFER_SIZE_BYTES) {
92	        bestCubeK = CUBE_K_128;
93	    } else if (
94	        Cube_M * CUBE_K_64 * HALF_SIZE_BYTES <= MEM_BUFFER_SIZE_BYTES &&
95	        CUBE_K_64 * Cube_N * HALF_SIZE_BYTES <= MEM_BUFFER_SIZE_BYTES) {
96	        bestCubeK = CUBE_K_64;
97	    }
98	
99	    return bestCubeK;
100	}
101	
102	// Deduce layout_t from SLayouts
103	template <typename TileDataA, typename TileDataB>
104	AICORE inline constexpr layout_t deduce_layout()
105	{
106	    if constexpr (TileDataA::SFractal == SLayout::RowMajor && TileDataB::SFractal == SLayout::RowMajor)
107	        return layout_t::NN;
108	    if constexpr (TileDataA::SFractal == SLayout::RowMajor && TileDataB::SFractal == SLayout::ColMajor)
109	        return layout_t::NT;
110	    if constexpr (TileDataA::SFractal == SLayout::ColMajor && TileDataB::SFractal == SLayout::RowMajor)
111	        return layout_t::TN;
112	    if constexpr (TileDataA::SFractal == SLayout::ColMajor && TileDataB::SFractal == SLayout::ColMajor)
113	        return layout_t::TT;
114	    return layout_t::NONE;
115	}
116	
117	struct MatmulCallConfig {
118	    bool useAcc;    // true -> TMATMUL_UF_ACC, false -> TMATMUL_UF
119	    AccPhase phase; // UF mapping
120	};
121	
122	AICORE inline MatmulCallConfig resolve_acc_mode(AccMode mode, bool isFirstSlice, bool isLastSlice)
123	{
124	    switch (mode) {
125	        case AccMode::Init:
126	            return MatmulCallConfig{!isFirstSlice, AccPhase::Unknown};
127	        case AccMode::Acc:
128	            return MatmulCallConfig{true, AccPhase::Unknown};
129	        case AccMode::InitPartialSum:
130	            return MatmulCallConfig{!isFirstSlice, AccPhase::Partial};
131	        case AccMode::InitFinalSum:
132	            return MatmulCallConfig{!isFirstSlice, AccPhase::Final};
133	        case AccMode::AccPartialSum:
134	            return MatmulCallConfig{true, AccPhase::Partial};
135	        case AccMode::AccFinalSum:
136	            return MatmulCallConfig{true, AccPhase::Final};
137	    }
138	    return MatmulCallConfig{!isFirstSlice, AccPhase::Partial};
139	}
140	
141	template <
142	    unsigned Cube_M, unsigned Tile_K, unsigned Cube_N, layout_t LAYOUT = layout_t::NONE, typename TileDataA,
143	    typename TileDataB, typename TileDataC>
144	AICORE inline void pto_macro_matmul(
145	    TileDataA& aMatTile, TileDataB& bMatTile, TileDataC& cAccTile, AccMode accMode = AccMode::Init)
146	{
147	    constexpr layout_t layout = deduce_layout<TileDataA, TileDataB>();
148	
149	    static_assert(layout != layout_t::NONE, "Deduced layout is NONE, check tile SLayouts");
150	    // Assert that template LAYOUT matches deduced layout if LAYOUT is not NONE
151	    if constexpr (LAYOUT != layout_t::NONE) {
152	        static_assert(
153	            LAYOUT == layout, "Layout mismatch: template LAYOUT does not match deduced layout from tile SLayouts. "
154	                              "Check SLayout of TileDataA and TileDataB.");
155	    }
156	
157	    // Ping-pong is used to overlap TEXTRACT (L1->L0) with TMATMUL on alternating buffers.
158	    uint64_t pingpong = getPingPong(0);
159	    const uint64_t Cube_K =
160	        calculateFittingCubeK(Cube_M, Cube_N) > Tile_K ? Tile_K : calculateFittingCubeK(Cube_M, Cube_N);
161	    const uint64_t kSegments = (uint64_t)(Tile_K / Cube_K);
162	    for (uint64_t k = 0; k < kSegments; k++) {
163	        using LeftTile = TileLeft<half, Cube_M, Cube_K, Cube_M, Cube_K>;
164	        LeftTile al0Tiles[2] = {LeftTile(), LeftTile()};
165	        using RightTile = TileRight<half, Cube_K, Cube_N, Cube_K, Cube_N>;
166	        RightTile bl0Tiles[2] = {RightTile(), RightTile()};
167	
168	        TASSIGN(al0Tiles[0], (uint64_t)L0A_BUF0);
169	        TASSIGN(al0Tiles[1], (uint64_t)L0A_BUF1);
170	        TASSIGN(bl0Tiles[0], (uint64_t)L0B_BUF0);
171	        TASSIGN(bl0Tiles[1], (uint64_t)L0B_BUF1);
172	
173	        // Wait until previous TMATMUL finishes using this L0 buffer before overwriting it via TEXTRACT.
174	        wait_flag(PIPE_M, PIPE_MTE1, pingpong);
175	
176	        if (layout == layout_t::NT) {
177	            TASSIGN(aMatTile, (uint64_t)aMatTile.data() + k * Cube_K * Cube_M * sizeof(typename TileDataA::DType));
178	            TASSIGN(bMatTile, (uint64_t)bMatTile.data() + k * Cube_K * Cube_N * sizeof(typename TileDataB::DType));
179	        }
180	
181	        // TEXTRACT slices the current Cube_K panel into L0A/L0B.
182	        TEXTRACT(al0Tiles[pingpong], aMatTile, 0, 0);
183	        TEXTRACT(bl0Tiles[pingpong], bMatTile, 0, 0);
184	
185	        set_flag(PIPE_MTE1, PIPE_M, pingpong);
186	        wait_flag(PIPE_MTE1, PIPE_M, pingpong);
187	
188	        const bool isLast = (k + 1 == kSegments);
189	        MatmulCallConfig cfg = resolve_acc_mode(accMode, k == 0, isLast);
190	        if (cfg.useAcc) {
191	            if (cfg.phase == AccPhase::Final) {
192	                TMATMUL_ACC<AccPhase::Final>(cAccTile, al0Tiles[pingpong], bl0Tiles[pingpong]);
193	            } else if (cfg.phase == AccPhase::Partial) {
194	                TMATMUL_ACC<AccPhase::Partial>(cAccTile, al0Tiles[pingpong], bl0Tiles[pingpong]);
195	            } else {
196	                TMATMUL_ACC(cAccTile, al0Tiles[pingpong], bl0Tiles[pingpong]);
197	            }
198	        } else {
199	            if (cfg.phase == AccPhase::Final) {
200	                TMATMUL<AccPhase::Final>(cAccTile, al0Tiles[pingpong], bl0Tiles[pingpong]);
201	            } else if (cfg.phase == AccPhase::Partial) {
202	                TMATMUL<AccPhase::Partial>(cAccTile, al0Tiles[pingpong], bl0Tiles[pingpong]);
203	            } else {
204	                TMATMUL(cAccTile, al0Tiles[pingpong], bl0Tiles[pingpong]);
205	            }
206	        }
207	        set_flag(PIPE_M, PIPE_MTE1, pingpong);
208	        pingpong = getPingPong(1);
209	    }
210	}
211	} // namespace pto
212	
213	#endif // PTO_MACRO_MATMUL_H
