59	float max_abs_diff(const std::vector<float>& a, const std::vector<float>& b)
60	{
61	    float m = 0.0f;
62	    for (std::size_t i = 0; i < a.size(); ++i) {
63	        m = std::max(m, std::abs(a[i] - b[i]));
64	    }
65	    return m;
66	}
