79	VerifyStats verify_allclose(
80	    const std::vector<float>& actual, const std::vector<float>& ref, float abs_tol, float rel_tol, float denom_eps)
81	{
82	    VerifyStats stats;
83	    if (actual.size() != ref.size() || actual.empty()) {
84	        stats.bad_count = std::max(actual.size(), ref.size());
85	        return stats;
86	    }
87	
88	    double sum_abs = 0.0;
89	    double sum_sq = 0.0;
90	    for (std::size_t i = 0; i < actual.size(); ++i) {
91	        const float a = actual[i];
92	        const float r = ref[i];
93	        if (!std::isfinite(a) || !std::isfinite(r)) {
94	            stats.has_nan_or_inf = true;
95	            ++stats.bad_count;
96	            continue;
97	        }
98	
99	        const float abs_diff = std::abs(a - r);
100	        const float denom = std::max(std::abs(r), denom_eps);
101	        const float rel_diff = abs_diff / denom;
102	
103	        sum_abs += static_cast<double>(abs_diff);
104	        sum_sq += static_cast<double>(abs_diff) * static_cast<double>(abs_diff);
105	
106	        if (abs_diff > stats.max_abs) {
107	            stats.max_abs = abs_diff;
108	            stats.max_abs_idx = i;
109	        }
110	        if (rel_diff > stats.max_rel) {
111	            stats.max_rel = rel_diff;
112	            stats.max_rel_idx = i;
113	        }
114	
115	        const float allowed = abs_tol + rel_tol * std::abs(r);
116	        if (!(abs_diff <= allowed)) {
117	            ++stats.bad_count;
118	        }
119	    }
120	
121	    const double n = static_cast<double>(actual.size());
122	    stats.mean_abs = static_cast<float>(sum_abs / n);
123	    stats.rmse = static_cast<float>(std::sqrt(sum_sq / n));
124	    return stats;
125	}
126	
127	void flash_attention_reference(
128	    const std::vector<float>& q, const std::vector<float>& k, const std::vector<float>& v, std::vector<float>& out,
129	    int batch, int heads, int seq_len, int head_dim, bool causal)
130	{
131	    const float scale = 1.0f / std::sqrt(static_cast<float>(head_dim));
132	
133	    for (int b = 0; b < batch; ++b) {
134	        for (int h = 0; h < heads; ++h) {
135	            for (int i = 0; i < seq_len; ++i) {
136	                const float* q_row = &q[idx4(b, h, i, 0, heads, seq_len, head_dim)];
137	
138	                const int j_limit = causal ? (i + 1) : seq_len;
139	                std::vector<float> scores(static_cast<std::size_t>(j_limit), 0.0f);
140	                float max_score = -std::numeric_limits<float>::infinity();
141	                for (int j = 0; j < j_limit; ++j) {
142	                    const float* k_row = &k[idx4(b, h, j, 0, heads, seq_len, head_dim)];
143	                    const float score = dot_qk(q_row, k_row, head_dim) * scale;
144	                    scores[static_cast<std::size_t>(j)] = score;
145	                    max_score = std::max(max_score, score);
146	                }
147	
148	                float denom = 0.0f;
149	                for (int j = 0; j < j_limit; ++j) {
150	                    scores[static_cast<std::size_t>(j)] = std::exp(scores[static_cast<std::size_t>(j)] - max_score);
151	                    denom += scores[static_cast<std::size_t>(j)];
152	                }
153	                const float inv_denom = (denom > 0.0f) ? (1.0f / denom) : 0.0f;
154	
155	                float* o_row = &out[idx4(b, h, i, 0, heads, seq_len, head_dim)];
156	                for (int d = 0; d < head_dim; ++d) {
157	                    o_row[d] = 0.0f;
158	                }
159	                for (int j = 0; j < j_limit; ++j) {
160	                    const float w = scores[static_cast<std::size_t>(j)] * inv_denom;
161	                    const float* v_row = &v[idx4(b, h, j, 0, heads, seq_len, head_dim)];
162	                    for (int d = 0; d < head_dim; ++d) {
163	                        o_row[d] += w * v_row[d];
164	                    }
165	                }
166	            }
167	        }
168	    }
169	}
